  [libraryController],
);
// Expose an accessible action: jump to the currently playing track via
// keyboard shortcut (Ctrl+J) when a track is playing.
final playingPathForShortcut = context.select<PlaybackController, String?>(
  (player) => player.songInfo?.track.path,
);

useEffect(() {
  return ownsLibraryController ? libCtrl.dispose : null;
}, [libCtrl]);

